import java.util.Scanner;

public class Main {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int[] input = readTwoInts(scanner);
        int n = input[0];
        int m = input[1];
        System.out.println(calculate(n, m));
        scanner.close();
    }

    static int[] readTwoInts(Scanner scanner) {
        int a = scanner.nextInt();
        int b = scanner.nextInt();
        return new int[] {a, b};
    }

    static int calculate(int n, int M) {
        int[][][] K = new int[n][][];
        K[0] = new int[][]{{1}};
        for (int i = 0; i < n - 1; i++) {
            int[][] prevLayer = K[i];
            int sizePrev = prevLayer.length;
            int[][] newLayer = new int[sizePrev + i + 1][i + 2];
            K[i + 1] = newLayer;
            for (int j = 0; j < sizePrev; j++) {
                for (int k = 0; k < prevLayer[j].length; k++) {
                    for (int h = 0; h < i + 1; h++) {
                        newLayer[j + h][k] = (newLayer[j + h][k] + prevLayer[j][k]) % M;
                    }
                }
                for (int k = 0; k < prevLayer[j].length; k++) {
                    newLayer[j + i + 1][i + 1] = (newLayer[j + i + 1][i + 1] + prevLayer[j][k]) % M;
                }
            }
        }
        int[] C = computeCoeffs(n, M);
        int total = 0;
        for (int i = 1; i < n; i++) {
            int[][] layer = K[i];
            int ni = layer.length;
            int mi = layer[0].length;
            int[][] S = new int[ni][mi];
            for (int j = 0; j < ni; j++) {
                System.arraycopy(layer[j], 0, S[j], 0, mi);
            }
            for (int j = 0; j < ni; j++) {
                for (int k = mi - 2; k >= 0; k--) {
                    S[j][k] = (S[j][k] + S[j][k + 1]) % M;
                }
            }
            for (int j = 1; j < ni; j++) {
                for (int k = 0; k < mi; k++) {
                    S[j][k] = (S[j][k] + S[j - 1][k]) % M;
                }
            }
            long sum_i = 0;
            for (int j = 1; j < ni; j++) {
                for (int k = 0; k < mi - 1; k++) {
                    sum_i += (long)layer[j][k] * S[j - 1][k + 1];
                    sum_i %= M;
                }
            }
            int c = C[i + 1];
            sum_i = (sum_i * c) % M;
            total = (total + (int)sum_i) % M;
        }
        return total;
    }

    static int[] computeCoeffs(int n, int M) {
        int[] C = new int[n + 1];
        C[n] = 1;
        for (int k = n - 1; k >= 0; k--) {
            C[k] = (int)((long)C[k + 1] * (k + 1) % M);
            if (C[k] == 0) {
                break;
            }
        }
        return C;
    }

    static int egcdVariant(int a, int b) {
        int rA = a, rB = b;
        int sA = 1, sB = 0;
        int tA = 0, tB = 1;
        while (rB != 0) {
            int q = rA / rB;
            int rTemp = rA - q * rB;
            rA = rB;
            rB = rTemp;
            int sTemp = sA - q * sB;
            sA = sB;
            sB = sTemp;
            int tTemp = tA - q * tB;
            tA = tB;
            tB = tTemp;
        }
        return rA;
    }
}

